/**
  * Tokenizer module for converting various input types to standardized string tokens.
  *
  * Scala translation of Python tokenizer with proper handling of:
  * - Type hierarchies and trait-based abstractions
  * - Variance in generics (covariance, contravariance, invariance)
  * - Pattern matching for type-safe dispatch
  * - Immutable data structures using case classes
  * - Option/Try/Either for error handling
  * - Function composition and functional programming idioms
  */

import scala.collection.immutable._
import scala.math.BigDecimal
import scala.util.{Try, Using}
import scala.io.Codec
import scala.reflect.ClassTag
import java.time.{LocalDate, LocalDateTime, ZonedDateTime, Instant}
import java.time.format.DateTimeFormatter
import scala.collection.mutable

// ============================================================================
// Enums and Constants
// ============================================================================

/**
  * Enumeration of token types.
  */
sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }

  // For pattern matching and serialization
  def apply(name: String): TokenType = name match {
    case "string" => String
    case "numeric" => Numeric
    case "temporal" => Temporal
    case "structured" => Structured
    case "binary" => Binary
    case "null" => Null
    case _ => throw new IllegalArgumentException(s"Unknown token type: $name")
  }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
  * Immutable token representation.
  *
  * @param value The token string value
  * @param tokenType The type of token
  * @param metadata Optional metadata associated with the token
  */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
    * Return new token with additional metadata.
    */
  def withMetadata(newMetadata: (String, Any)*): Token =
    this.copy(metadata = metadata ++ newMetadata.toMap)

  /**
    * Merge metadata from another token.
    */
  def mergeMetadata(other: Map[String, Any]): Token =
    this.copy(metadata = metadata ++ other)
}

/**
  * Mutable batch of tokens for collecting results.
  * Not thread-safe; suitable for single-threaded batch operations.
  */
final class TokenBatch {
  private val tokens = scala.collection.mutable.Buffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def addAll(ts: Iterable[Token]): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens ++= ts
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def toList: List[Token] = tokens.toList

  def size: Int = tokens.size

  def isEmpty: Boolean = tokens.isEmpty
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
  * Covariant container - can return subtypes.
  * Used for read-only collections where variance is beneficial.
  */
final class TokenContainer[+T](items: Seq[T]) {
  private val itemsSeq: Vector[T] = items.toVector

  def getAll: Vector[T] = itemsSeq

  def mapTokens[U](func: T => String): List[String] =
    itemsSeq.map(func).toList

  def size: Int = itemsSeq.size

  def isEmpty: Boolean = itemsSeq.isEmpty
}

object TokenContainer {
  def apply[T](items: T*): TokenContainer[T] = new TokenContainer(items)
}

/**
  * Contravariant sink - can accept supertypes.
  * Used for write-only operations where contravariance is beneficial.
  */
final class TokenSink[-T] {
  private val received = scala.collection.mutable.Buffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }

  def size: Int = received.size
}

/**
  * Invariant handler - exact type matching required.
  * Used when both reading and writing with the same type.
  */
final class TokenHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }

  def modify(func: T => Option[T]): Option[T] = {
    func(value).map { newVal =>
      value = newVal
      newVal
    }
  }
}

// ============================================================================
// Tokenizer Traits and Implementations
// ============================================================================

/**
  * Protocol/trait for objects that can be converted to tokens.
  */
trait Tokenizable {
  def toToken: String
}

/**
  * Abstract base tokenizer trait with generic input type.
  */
trait BaseTokenizer[T] {
  /**
    * Convert a value to a token.
    */
  def tokenize(value: T): Token

  /**
    * Lazy tokenization of multiple values.
    */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
    * Tokenize and collect results into a list.
    */
  def tokenizeList(values: Iterable[T]): List[Token] =
    tokenizeBatch(values).toList

  /**
    * Tokenize with error handling.
    */
  def tokenizeSafe(value: T): Try[Token] =
    Try(tokenize(value))
}

/**
  * Tokenizer for string and bytes types.
  */
final class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.String)
  }

  def tokenizeBytes(bytes: Array[Byte]): Token = {
    val str = new String(bytes, encoding)
    tokenize(str)
  }
}

object StringTokenizer {
  def apply(): StringTokenizer = new StringTokenizer()
  def apply(encoding: String): StringTokenizer = new StringTokenizer(encoding)
  def apply(encoding: String, normalizer: String => String): StringTokenizer =
    new StringTokenizer(encoding, normalizer)
}

/**
  * Tokenizer for numeric types with precision handling.
  */
sealed trait NumericTokenizer extends BaseTokenizer[Any] {
  protected val precision: Int
  protected val formatOptions: Map[String, Any]

  def tokenize(value: Any): Token = value match {
    case d: BigDecimal => tokenizeDecimal(d)
    case f: Float => tokenizeFloat(f)
    case d: Double => tokenizeDouble(d)
    case i: Int => tokenizeInt(i)
    case l: Long => tokenizeLong(l)
    case other => Token(other.toString, TokenType.Numeric, Map("fallback" -> true))
  }

  protected def tokenizeInt(value: Int): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Int"))

  protected def tokenizeLong(value: Long): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Long"))

  protected def tokenizeFloat(value: Float): Token = {
    val formatted = f"$value%.${precision}f"
    Token(formatted, TokenType.Numeric, Map("original_type" -> "Float"))
  }

  protected def tokenizeDouble(value: Double): Token = {
    val formatted = f"$value%.${precision}f"
    Token(formatted, TokenType.Numeric, Map("original_type" -> "Double"))
  }

  protected def tokenizeDecimal(value: BigDecimal): Token = {
    val formatted = f"$value%.${precision}f"
    Token(formatted, TokenType.Numeric, Map("original_type" -> "BigDecimal"))
  }
}

object NumericTokenizer {
  def apply(): NumericTokenizer = apply(6, Map.empty)
  def apply(precision: Int): NumericTokenizer = apply(precision, Map.empty)
  def apply(precision: Int, formatOptions: Map[String, Any]): NumericTokenizer =
    new NumericTokenizer {
      protected val precision: Int = precision
      protected val formatOptions: Map[String, Any] = formatOptions
    }
}

/**
  * Tokenizer for date/time types.
  */
sealed trait TemporalTokenizer extends BaseTokenizer[Any] {
  protected val formatStr: Option[String]

  def tokenize(value: Any): Token = value match {
    case date: LocalDate => tokenizeDate(date)
    case dateTime: LocalDateTime => tokenizeDateTime(dateTime)
    case zdt: ZonedDateTime => tokenizeZonedDateTime(zdt)
    case inst: Instant => tokenizeInstant(inst)
    case other => Token(other.toString, TokenType.Temporal)
  }

  protected def tokenizeDate(date: LocalDate): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern(_))
      .getOrElse(DateTimeFormatter.ISO_LOCAL_DATE)
    Token(date.format(formatter), TokenType.Temporal)
  }

  protected def tokenizeDateTime(dateTime: LocalDateTime): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern(_))
      .getOrElse(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
    Token(dateTime.format(formatter), TokenType.Temporal)
  }

  protected def tokenizeZonedDateTime(zdt: ZonedDateTime): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern(_))
      .getOrElse(DateTimeFormatter.ISO_ZONED_DATE_TIME)
    Token(zdt.format(formatter), TokenType.Temporal)
  }

  protected def tokenizeInstant(instant: Instant): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern(_))
      .getOrElse(DateTimeFormatter.ISO_INSTANT)
    Token(instant.toString, TokenType.Temporal)
  }
}

object TemporalTokenizer {
  def apply(): TemporalTokenizer = apply(None)
  def apply(formatStr: String): TemporalTokenizer = apply(Some(formatStr))
  def apply(formatStr: Option[String]): TemporalTokenizer =
    new TemporalTokenizer {
      protected val formatStr: Option[String] = formatStr
    }
}

// ============================================================================
// Universal Tokenizer with Pattern Matching Dispatch
// ============================================================================

/**
  * Tokenizer that handles multiple types using pattern matching.
  * Type-safe dispatch based on runtime values.
  */
final class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.Null)
    case tokenizable: Tokenizable =>
      Token(tokenizable.toToken, TokenType.Structured)
    case str: String =>
      stringTokenizer.tokenize(str)
    case bytes: Array[Byte] =>
      stringTokenizer.tokenizeBytes(bytes)
    case i: Int =>
      numericTokenizer.tokenize(i)
    case l: Long =>
      numericTokenizer.tokenize(l)
    case f: Float =>
      numericTokenizer.tokenize(f)
    case d: Double =>
      numericTokenizer.tokenize(d)
    case bd: BigDecimal =>
      numericTokenizer.tokenize(bd)
    case date: LocalDate =>
      temporalTokenizer.tokenize(date)
    case dateTime: LocalDateTime =>
      temporalTokenizer.tokenize(dateTime)
    case zdt: ZonedDateTime =>
      temporalTokenizer.tokenize(zdt)
    case inst: Instant =>
      temporalTokenizer.tokenize(inst)
    case b: Boolean =>
      Token(b.toString, TokenType.String)
    case _ =>
      // Fallback: convert to string
      Token(value.toString, TokenType.String, Map("fallback" -> true))
  }

  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] =
    values.iterator.map(tokenize)

  def tokenizeList(values: Iterable[Any]): List[Token] =
    tokenizeBatch(values).toList
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer()
}

// ============================================================================
// Token Registry with Complex Nested Generics
// ============================================================================

/**
  * Registry with complex nested generic types.
  * Manages containers and handlers for type-specific processing.
  */
final class TokenRegistry[T] {
  private val registry = scala.collection.mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = scala.collection.mutable.Buffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator.map(_.apply(item)).find(_.isDefined).flatten
        }.toList
      case None =>
        List.empty
    }
  }

  def processWithDefault(key: String): List[Token] = {
    process(key).map {
      case Some(token) => token
      case None => Token("UNPROCESSED", TokenType.Null)
    }
  }

  def clear(): Unit = {
    registry.clear()
    handlers.clear()
  }
}

object TokenRegistry {
  def apply[T](): TokenRegistry[T] = new TokenRegistry[T]()
}

// ============================================================================
// Functor and Monad for Tokens
// ============================================================================

/**
  * Simple functor for tokens providing map and flatMap operations.
  */
sealed trait TokenFunctor[+A] {
  def map[B](func: A => B): TokenFunctor[B]

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B]

  def getOrElse[B >: A](default: B): B

  def toOption: Option[A]
}

object TokenFunctor {
  case class Pure[A](value: A) extends TokenFunctor[A] {
    def map[B](func: A => B): TokenFunctor[B] = Pure(func(value))

    def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] = func(value)

    def getOrElse[B >: A](default: B): B = value

    def toOption: Option[A] = Some(value)
  }

  case class Empty[A]() extends TokenFunctor[A] {
    def map[B](func: A => B): TokenFunctor[B] = Empty[B]()

    def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] = Empty[B]()

    def getOrElse[B >: A](default: B): B = default

    def toOption: Option[A] = None
  }

  def apply[A](value: A): TokenFunctor[A] = Pure(value)

  def empty[A]: TokenFunctor[A] = Empty[A]()
}

/**
  * Monad extending functor with additional operations.
  */
sealed trait TokenMonad[+A] extends TokenFunctor[A] {
  def ap[B](func: TokenMonad[A => B]): TokenMonad[B]
}

object TokenMonad {
  case class Pure[A](value: A) extends TokenMonad[A] {
    def map[B](func: A => B): TokenMonad[B] = Pure(func(value))

    def flatMap[B](func: A => TokenMonad[B]): TokenMonad[B] = func(value)

    def getOrElse[B >: A](default: B): B = value

    def toOption: Option[A] = Some(value)

    def ap[B](func: TokenMonad[A => B]): TokenMonad[B] = func.flatMap(f => map(f))
  }

  case class Empty[A]() extends TokenMonad[A] {
    def map[B](func: A => B): TokenMonad[B] = Empty[B]()

    def flatMap[B](func: A => TokenMonad[B]): TokenMonad[B] = Empty[B]()

    def getOrElse[B >: A](default: B): B = default

    def toOption: Option[A] = None

    def ap[B](func: TokenMonad[A => B]): TokenMonad[B] = Empty[B]()
  }

  def apply[A](value: A): TokenMonad[A] = Pure(value)

  def empty[A]: TokenMonad[A] = Empty[A]()
}

// ============================================================================
// JSON Value and Tokenizer
// ============================================================================

/**
  * Sealed trait representing JSON values for type-safe JSON handling.
  */
sealed trait JsonValue

object JsonValue {
  case object Null extends JsonValue
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  def fromString(value: String): JsonValue = JsonString(value)
  def fromNumber(value: Double): JsonValue = JsonNumber(value)
  def fromBoolean(value: Boolean): JsonValue = JsonBoolean(value)
  def fromArray(values: Vector[JsonValue]): JsonValue = JsonArray(values)
  def fromObject(fields: Map[String, JsonValue]): JsonValue = JsonObject(fields)
}

/**
  * Tokenizer for JSON structures.
  */
final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    navigatePath(value, parts).map(tokenize)
  }

  private def toJsonString(value: JsonValue): String = value match {
    case JsonValue.Null => "null"
    case JsonValue.JsonString(s) => s""""$s""""
    case JsonValue.JsonNumber(n) => n.toString
    case JsonValue.JsonBoolean(b) => b.toString
    case JsonValue.JsonArray(arr) =>
      arr.map(toJsonString).mkString("[", ", ", "]")
    case JsonValue.JsonObject(fields) =>
      fields
        .map { case (k, v) => s""""$k": ${toJsonString(v)}""" }
        .mkString("{", ", ", "}")
  }

  private def navigatePath(value: JsonValue, path: List[String]): Option[JsonValue] = {
    path match {
      case Nil => Some(value)
      case part :: rest =>
        value match {
          case JsonValue.JsonObject(fields) =>
            fields.get(part).flatMap(navigatePath(_, rest))
          case JsonValue.JsonArray(arr) =>
            part.toIntOption.flatMap { idx =>
              if (idx >= 0 && idx < arr.length) {
                navigatePath(arr(idx), rest)
              } else {
                None
              }
            }
          case _ => None
        }
    }
  }
}

object JsonTokenizer {
  def apply(): JsonTokenizer = new JsonTokenizer()
  def apply(pretty: Boolean): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
  * Basic tokenizer that splits text by whitespace.
  * Fundamental tokenization operation used in NLP and text processing.
  */
final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set(".,!?;:'\"()[]{}")

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList
    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    text.split("\\s+").foldLeft((List.empty[(String, Int, Int)], 0)) {
      case ((acc, currentPos), word) =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length
        val processed = processToken(word)
        val newAcc = processed match {
          case Some(p) => acc :+ (p, start, end)
          case None => acc
        }
        (newAcc, end)
    }._1
  }

  def countTokens(text: String): Int =
    tokenize(text).length

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.replaceAll(s"[${punctuation.map(java.util.regex.Pattern.quote(_)).mkString}]", "")
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      return None
    }

    val truncated = maxLength match {
      case Some(max) => processed.take(max)
      case None => processed
    }

    if (truncated.isEmpty) None else Some(truncated)
  }
}

object WhitespaceTokenizer {
  def apply(): WhitespaceTokenizer = new WhitespaceTokenizer()

  def apply(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer =
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
  * Fluent builder for creating custom tokenizers.
  * Type-safe method chaining with proper return types.
  */
final class TokenizerBuilder[T](
  private val normalizers: List[String => String] = List.empty,
  private val validators: List[T => Boolean] = List.empty,
  private val metadata: Map[String, Any] = Map.empty
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(newMetadata: (String, Any)*): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators, metadata ++ newMetadata.toMap)

  def build(): T => Token = { value: T =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.String, metadata)
  }

  def buildTry(): T => Try[Token] = { value: T =>
    Try {
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

// ============================================================================
// Utility Functions for Tokenization
// ============================================================================

/**
  * Tokenize a single value using the universal tokenizer.
  */
def tokenize(value: Any): Token =
  UniversalTokenizer().tokenize(value)

/**
  * Tokenize multiple values as a batch.
  */
def tokenizeBatch(values: Iterable[Any]): List[Token] =
  UniversalTokenizer().tokenizeList(values)

/**
  * Convert value to token with metadata.
  */
def toToken(value: Any, metadata: (String, Any)*): Token =
  tokenize(value).withMetadata(metadata: _*)

/**
  * Add metadata to an existing token.
  */
def withMetadata(token: Token, metadata: (String, Any)*): Token =
  token.withMetadata(metadata: _*)

