/**
  * Sealed trait representing JSON values for type-safe JSON handling.
  */
sealed trait JsonValue

object JsonValue {
  case object Null extends JsonValue
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue
  case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  def fromString(value: String): JsonValue = JsonString(value)
  def fromNumber(value: Double): JsonValue = JsonNumber(value)
  def fromBoolean(value: Boolean): JsonValue = JsonBoolean(value)
  def fromArray(values: Vector[JsonValue]): JsonValue = JsonArray(values)
  def fromObject(fields: Map[String, JsonValue]): JsonValue = JsonObject(fields)
}

/**
  * Tokenizer for JSON structures.
  */
final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    navigatePath(value, parts).map(tokenize)
  }

  private def toJsonString(value: JsonValue): String = value match {
    case JsonValue.Null => "null"
    case JsonValue.JsonString(s) => s""""$s""""
    case JsonValue.JsonNumber(n) => n.toString
    case JsonValue.JsonBoolean(b) => b.toString
    case JsonValue.JsonArray(arr) =>
      arr.map(toJsonString).mkString("[", ", ", "]")
    case JsonValue.JsonObject(fields) =>
      fields
        .map { case (k, v) => s""""$k": ${toJsonString(v)}""" }
        .mkString("{", ", ", "}")
  }

  private def navigatePath(value: JsonValue, path: List[String]): Option[JsonValue] = {
    path match {
      case Nil => Some(value)
      case part :: rest =>
        value match {
          case JsonValue.JsonObject(fields) =>
            fields.get(part).flatMap(navigatePath(_, rest))
          case JsonValue.JsonArray(arr) =>
            part.toIntOption.flatMap { idx =>
              if (idx >= 0 && idx < arr.length) {
                navigatePath(arr(idx), rest)
              } else {
                None
              }
            }
          case _ => None
        }
    }
  }
}

object JsonTokenizer {
  def apply(): JsonTokenizer = new JsonTokenizer()
  def apply(pretty: Boolean): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
  * Basic tokenizer that splits text by whitespace.
  * Fundamental tokenization operation used in NLP and text processing.
  */
final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set(".,!?;:'\"()[]{}")

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toList
    words.zipWithIndex.flatMap { case (word, idx) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    text.split("\\s+").foldLeft((List.empty[(String, Int, Int)], 0)) {
      case ((acc, currentPos), word) =>
        val start = text.indexOf(word, currentPos)
        val end = start + word.length
        val processed = processToken(word)
        val newAcc = processed match {
          case Some(p) => acc :+ (p, start, end)
          case None => acc
        }
        (newAcc, end)
    }._1
  }

  def countTokens(text: String): Int =
    tokenize(text).length

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.replaceAll(s"[${punctuation.map(java.util.regex.Pattern.quote(_)).mkString}]", "")
    }

    if (lowercase) {
      processed = processed.toLowerCase()
    }

    if (processed.length < minLength) {
      return None
    }

    val truncated = maxLength match {
      case Some(max) => processed.take(max)
      case None => processed
    }

    if (truncated.isEmpty) None else Some(truncated)
  }
}

object WhitespaceTokenizer {
  def apply(): WhitespaceTokenizer = new WhitespaceTokenizer()

  def apply(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
  ): WhitespaceTokenizer =
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
  * Fluent builder for creating custom tokenizers.
  * Type-safe method chaining with proper return types.
  */
final class TokenizerBuilder[T](
  private val normalizers: List[String => String] = List.empty,
  private val validators: List[T => Boolean] = List.empty,
  private val metadata: Map[String, Any] = Map.empty
) {
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(newMetadata: (String, Any)*): TokenizerBuilder[T] =
    new TokenizerBuilder(normalizers, validators, metadata ++ newMetadata.toMap)

  def build(): T => Token = { value: T =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.String, metadata)
  }

  def buildTry(): T => Try[Token] = { value: T =>
    Try {
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

