def tokenize(value: Any): Token =
  UniversalTokenizer().tokenize(value)

/**
  * Tokenize multiple values as a batch.
  */
def tokenizeBatch(values: Iterable[Any]): List[Token] =
  UniversalTokenizer().tokenizeList(values)

/**
  * Convert value to token with metadata.
  */
def toToken(value: Any, metadata: (String, Any)*): Token =
  tokenize(value).withMetadata(metadata: _*)

/**
  * Add metadata to an existing token.
  */
def withMetadata(token: Token, metadata: (String, Any)*): Token =
  token.withMetadata(metadata: _*)

