/**
  * Immutable token representation.
  *
  * @param value The token string value
  * @param tokenType The type of token
  * @param metadata Optional metadata associated with the token
  */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
    * Return new token with additional metadata.
    */
  def withMetadata(newMetadata: (String, Any)*): Token =
    this.copy(metadata = metadata ++ newMetadata.toMap)

  /**
    * Merge metadata from another token.
    */
  def mergeMetadata(other: Map[String, Any]): Token =
    this.copy(metadata = metadata ++ other)
}

/**
  * Mutable batch of tokens for collecting results.
  * Not thread-safe; suitable for single-threaded batch operations.
  */
final class TokenBatch {
  private val tokens = scala.collection.mutable.Buffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def addAll(ts: Iterable[Token]): Unit = {
    if (processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens ++= ts
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def toList: List[Token] = tokens.toList

  def size: Int = tokens.size

  def isEmpty: Boolean = tokens.isEmpty
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
  * Covariant container - can return subtypes.
  * Used for read-only collections where variance is beneficial.
  */
final class TokenContainer[+T](items: Seq[T]) {
  private val itemsSeq: Vector[T] = items.toVector

  def getAll: Vector[T] = itemsSeq

  def mapTokens[U](func: T => String): List[String] =
    itemsSeq.map(func).toList

  def size: Int = itemsSeq.size

  def isEmpty: Boolean = itemsSeq.isEmpty
}

object TokenContainer {
  def apply[T](items: T*): TokenContainer[T] = new TokenContainer(items)
}

/**
  * Contravariant sink - can accept supertypes.
  * Used for write-only operations where contravariance is beneficial.
  */
final class TokenSink[-T] {
  private val received = scala.collection.mutable.Buffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }

  def size: Int = received.size
}

/**
  * Invariant handler - exact type matching required.
  * Used when both reading and writing with the same type.
  */
final class TokenHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(newValue: T): Unit = {
    value = newValue
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }

  def modify(func: T => Option[T]): Option[T] = {
    func(value).map { newVal =>
      value = newVal
      newVal
    }
  }
}

