}

/**
  * Tokenizer for numeric types with precision handling.
  */
sealed trait NumericTokenizer extends BaseTokenizer[Any] {
  protected val precision: Int
  protected val formatOptions: Map[String, Any]

  def tokenize(value: Any): Token = value match {
    case d: BigDecimal => tokenizeDecimal(d)
    case f: Float => tokenizeFloat(f)
    case d: Double => tokenizeDouble(d)
    case i: Int => tokenizeInt(i)
    case l: Long => tokenizeLong(l)
    case other => Token(other.toString, TokenType.Numeric, Map("fallback" -> true))
  }

  protected def tokenizeInt(value: Int): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Int"))

  protected def tokenizeLong(value: Long): Token =
    Token(value.toString, TokenType.Numeric, Map("original_type" -> "Long"))

  protected def tokenizeFloat(value: Float): Token = {
    val formatted = String.format(s"%.${precision}f", value: java.lang.Float)
    Token(formatted, TokenType.Numeric, Map("original_type" -> "Float"))
  }

  protected def tokenizeDouble(value: Double): Token = {
    val formatted = String.format(s"%.${precision}f", value: java.lang.Double)
    Token(formatted, TokenType.Numeric, Map("original_type" -> "Double"))
  }

  protected def tokenizeDecimal(value: BigDecimal): Token = {
    val formatted = value.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString()
    Token(formatted, TokenType.Numeric, Map("original_type" -> "BigDecimal"))
  }
}

